import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`lead-generation`,heroTitle:`Your 24/7 SDR team`,heroSubtitle:`Perplexity Computer finds your target accounts, builds your prospect lists, and drafts your outreach — automatically.`,inputUrlCta:`Build my pipeline`,inputUrlPlaceholder:`your ideal customer`,inputUrlPrefill:`Use this ideal customer description: {url}. Build a lead generation workflow. 1) Define the ideal customer profile, buying triggers, disqualifiers, target titles, company traits, and enrichment fields. 2) Research target accounts that match the profile and explain why each account fits. 3) Build a prospect list with roles, context, personalization angles, and CRM-ready fields. 4) Draft outreach sequences for Gmail, HubSpot, Salesforce, Slack review, and follow-up handoff. 5) Remember account fit rules, approved messaging, and reply patterns so future prospecting gets sharper.`,heroOverlaySteps:[`Defining your ICP, triggers, disqualifiers, and target titles`,`Researching target accounts and fit signals`,`Building prospect lists with personalization angles`,`Outreach drafts and pipeline packet ready to review`],generatingSteps:[`Reading {url} to understand your ideal customer and prospecting goals`,`Designing agents to research accounts, enrich prospects, and draft outreach`,`Configuring list fields, fit scoring, messaging, and CRM handoff`,`Preparing a pipeline packet with target accounts, prospects, and outreach drafts`],featureSectionTitle:`From ICP to pipeline packet`,featureCardTitles:[`Connects to your sales stack`,`Outputs ready for outreach`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Sheets, Slack, Notion, HubSpot, Salesforce — Computer keeps account research, lists, outreach, and CRM handoff connected.`,`Target accounts. Prospect lists. Fit notes. Personalization angles. Outreach drafts. Computer gives your sales team pipeline work they can review and run.`],capabilitySectionTitle:`Your lead generation team, on autopilot`,capabilitySectionSubtitle:`Describe your ideal customer, step away, and come back to target accounts, prospects, and outreach drafts.`,capabilityCards:[{title:`Prospect Lists`,description:`Computer can build structured prospect lists with roles, context, fit notes, personalization angles, and CRM-ready fields.`},{title:`Target Account Research`,description:`Computer can research companies that match your ICP, explain the fit, and surface triggers worth mentioning in outreach.`},{title:`Outreach Drafting`,description:`Computer can draft account-based emails, follow-ups, and Slack review notes that connect your offer to each prospect context.`},{title:`Connect Your Tools`,description:`Computer can organize pipeline work across Gmail, Google Sheets, Slack, Notion, HubSpot, and Salesforce so handoff stays clean.`},{title:`Remember & Learn`,description:`Computer can remember your ICP, disqualifiers, approved messaging, and reply patterns so future lists get more precise.`},{title:`Monitor & Alert`,description:`Computer can monitor account signals, stale prospects, and missing follow-ups, then alert you when pipeline work needs attention.`}]});export{t as default};
